function sudokuCountSolutions(board,limit){var rows=Array(9).fill(0),cols=Array(9).fill(0),boxes=Array(9).fill(0),full=511;for(var i=0;i<81;i++){var v=board[i];if(!v)continue;var r=Math.floor(i/9),c=i%9,b=Math.floor(r/3)*3+Math.floor(c/3),bit=1<<(v-1);if((rows[r]&bit)||(cols[c]&bit)||(boxes[b]&bit))return 0;rows[r]|=bit;cols[c]|=bit;boxes[b]|=bit;}function solve(){var best=-1,mask=0,min=10;for(var j=0;j<81;j++){if(board[j])continue;var rr=Math.floor(j/9),cc=j%9,bb=Math.floor(rr/3)*3+Math.floor(cc/3),opts=full&~(rows[rr]|cols[cc]|boxes[bb]),cnt=0;for(var z=opts;z;z&=z-1)cnt++;if(cnt<min){min=cnt;best=j;mask=opts;if(cnt<=1)break;}}if(best<0)return 1;if(min===0)return 0;var r2=Math.floor(best/9),c2=best%9,b2=Math.floor(r2/3)*3+Math.floor(c2/3),total=0;while(mask){var bit=mask&-mask;mask-=bit;board[best]=Math.log2(bit)+1;rows[r2]|=bit;cols[c2]|=bit;boxes[b2]|=bit;total+=solve();rows[r2]^=bit;cols[c2]^=bit;boxes[b2]^=bit;board[best]=0;if(total>=limit)return total;}return total;}return solve();}
function sudInit(){var digits=mix([1,2,3,4,5,6,7,8,9]),bands=mix([0,1,2]),stacks=mix([0,1,2]),rows=[],cols=[];bands.forEach(function(b){mix([0,1,2]).forEach(function(r){rows.push(b*3+r);});});stacks.forEach(function(b){mix([0,1,2]).forEach(function(c){cols.push(b*3+c);});});var sol=[];for(var r=0;r<9;r++)for(var c=0;c<9;c++){var base=(rows[r]*3+Math.floor(rows[r]/3)+cols[c])%9;sol.push(digits[base]);}var level=Number(localStorage.getItem("arenaSudokuLevel")||1),holes=Math.min(55,35+Math.floor((level-1)*1.5)),ids=mix(Array.from({length:81},function(_,i){return i;})),blank=[],board=sol.slice();for(var k=0;k<ids.length&&blank.length<holes;k++){var ix=ids[k];board[ix]=0;if(sudokuCountSolutions(board,2)===1)blank.push(ix);else board[ix]=sol[ix];}blank.sort(function(a,b){return a-b;});s={sol:sol,blank:blank,board:board,sel:blank[0],level:level,mistakes:0,startedAt:Date.now(),msg:"Her satır, sütun ve 3×3 kutuda 1–9 rakamları birer kez bulunmalı.",done:false};}
function sudValid(){for(var r=0;r<9;r++){var row=s.board.slice(r*9,r*9+9);if(row.some(function(v){return !v;})||new Set(row).size!==9)return false;}for(var c=0;c<9;c++){var col=[];for(var r=0;r<9;r++)col.push(s.board[r*9+c]);if(new Set(col).size!==9)return false;}for(var br=0;br<3;br++)for(var bc=0;bc<3;bc++){var box=[];for(var y=0;y<3;y++)for(var x=0;x<3;x++)box.push(s.board[(br*3+y)*9+bc*3+x]);if(new Set(box).size!==9)return false;}return true;}
function sudConflict(i){var v=s.board[i];if(!v)return false;var r=Math.floor(i/9),c=i%9;for(var k=0;k<81;k++){if(k===i||s.board[k]!==v)continue;var rr=Math.floor(k/9),cc=k%9;if(rr===r||cc===c||(Math.floor(rr/3)===Math.floor(r/3)&&Math.floor(cc/3)===Math.floor(c/3)))return true;}return false;}
