function mathQ(){var a=Math.floor(Math.random()*20)+5,b=Math.floor(Math.random()*15)+2,o=Math.floor(Math.random()*3);if(o===0){s.q=a+" + "+b;s.ans=a+b;}else if(o===1){if(b>a){var t=a;a=b;b=t;}s.q=a+" − "+b;s.ans=a-b;}else{a=Math.floor(Math.random()*9)+2;b=Math.floor(Math.random()*9)+2;s.q=a+" × "+b;s.ans=a*b;}}
