function game2048Init(){s={board:Array(16).fill(0),score:0,best:Number(localStorage.getItem("arena2048Best")||0),done:false,won:false,msg:"Aynı sayıları birleştir. 2048’e ulaş!"};g2048Add();g2048Add();}
function g2048Add(){var e=s.board.map(function(v,i){return v? -1:i;}).filter(function(v){return v>=0;});if(e.length)s.board[e[Math.floor(Math.random()*e.length)]]=Math.random()<.9?2:4;}
function game2048Move(dir){var before=s.board.join(","),b=s.board.slice();for(var line=0;line<4;line++){var ids=[];for(var k=0;k<4;k++){var r=dir==="up"?k:dir==="down"?3-k:line,c=dir==="left"?k:dir==="right"?3-k:line;ids.push(r*4+c);}var vals=ids.map(function(i){return b[i];}).filter(Boolean),out=[];for(var j=0;j<vals.length;j++){if(vals[j]===vals[j+1]){out.push(vals[j]*2);s.score+=vals[j]*2;j++;}else out.push(vals[j]);}while(out.length<4)out.push(0);ids.forEach(function(i,j){b[i]=out[j];});}s.board=b;if(before!==b.join(",")){g2048Add();if(s.score>s.best){s.best=s.score;localStorage.setItem("arena2048Best",String(s.best));}}s.won=s.board.indexOf(2048)>=0;s.done=s.won||!game2048CanMove();s.msg=s.won?"2048! Kazandın.":s.done?"Hamle kalmadı. Oyun bitti.":"Birleştirmeye devam et.";}
