function damaInit(){var b=Array(64).fill("");for(var r=0;r<3;r++)for(var c=0;c<8;c++)if((r+c)%2===1)b[r*8+c]="b";for(var rr=5;rr<8;rr++)for(var cc=0;cc<8;cc++)if((rr+cc)%2===1)b[rr*8+cc]="r";s={b:b,turn:"r",sel:-1,forced:-1,legal:[],done:false,msg:"Kırmızı taşlar sensin. Taş seç, sonra hedef kareye dokun.",moves:0};}
function damaSide(p){return p==="r"||p==="R"?"r":p==="b"||p==="B"?"b":"";}
function damaMovesFor(board,from,side,capturesOnly){var p=board[from],king=p===p.toUpperCase(),row=Math.floor(from/8),col=from%8,dirs=king?[-1,1]:side==="r"?[-1]:[1],out=[];for(var dr0=-1;dr0<=1;dr0+=2)for(var dc0=-1;dc0<=1;dc0+=2){var captureRow=row+dr0,captureCol=col+dc0,landRow=row+dr0*2,landCol=col+dc0*2;if(landRow>=0&&landRow<8&&landCol>=0&&landCol<8){var mid=captureRow*8+captureCol,to=landRow*8+landCol;if(board[mid]&&damaSide(board[mid])!==side&&!board[to])out.push({from:from,to:to,cap:mid,promote:side==="r"?landRow===0:landRow===7});}}if(capturesOnly)return out;for(var d=0;d<dirs.length;d++)for(var dc=-1;dc<=1;dc+=2){var nr=row+dirs[d],nc=col+dc;if(nr>=0&&nr<8&&nc>=0&&nc<8&&!board[nr*8+nc])out.push({from:from,to:nr*8+nc,cap:-1,promote:side==="r"?nr===0:nr===7});}return out;}
function damaLegal(board,side,forced){if(forced>=0)return damaMovesFor(board,forced,side,true);var captures=[];for(var i=0;i<64;i++)if(damaSide(board[i])===side)captures=captures.concat(damaMovesFor(board,i,side,true));if(captures.length)return captures;var moves=[];for(var j=0;j<64;j++)if(damaSide(board[j])===side)moves=moves.concat(damaMovesFor(board,j,side,false));return moves;}
function damaApply(board,m){var piece=board[m.from];board[m.from]="";board[m.to]=m.promote?(piece==="r"?"R":piece==="b"?"B":piece):piece;if(m.cap>=0)board[m.cap]="";}
function damaCount(board,side){return board.filter(function(p){return damaSide(p)===side;}).length;}
function damaEvaluateMove(board,m){var piece=board[m.from],score=m.cap>=0?100:0;if(m.promote)score+=45;var row=Math.floor(m.to/8),col=m.to%8;score+=Math.max(0,3-Math.abs(3.5-col))*1.5;if(piece==="b")score+=row*1.4;if(piece==="B")score+=7;var clone=board.slice();damaApply(clone,m);var threats=damaLegal(clone,"r",-1).filter(function(x){return x.cap>=0;});if(threats.some(function(x){return x.cap===m.to;}))score-=65;return score+Math.random()*2;}
function damaChoose(board,moves){return moves.slice().sort(function(a,b){return damaEvaluateMove(board,b)-damaEvaluateMove(board,a);})[0];}
function damaStatus(){var red=damaCount(s.b,"r"),black=damaCount(s.b,"b"),rm=damaLegal(s.b,"r",-1),bm=damaLegal(s.b,"b",-1);if(!red||!rm.length){s.done=true;s.msg="Bot kazandı. Yeni oyunla tekrar dene.";return;}if(!black||!bm.length){s.done=true;s.msg="Kazandın! Dama oyununu tamamladın.";return;}}
function damaBot(){var guard=0;while(s.turn==="b"&&!s.done&&guard++<20){var moves=damaLegal(s.b,"b",s.forced);if(!moves.length){s.turn="r";s.forced=-1;break;}var m=damaChoose(s.b,moves);damaApply(s.b,m);s.moves++;var chain=m.cap>=0?damaMovesFor(s.b,m.to,"b",true):[];if(chain.length){s.forced=m.to;continue;}s.forced=-1;s.turn="r";}damaStatus();s.msg=s.done?s.msg:"Sıra sende. Rakibin taşını alabiliyorsan almak zorundasın.";}
function damaHtml(){var moves=s.legal.map(function(m){return m.to;}),h=stats(["Sen: "+damaCount(s.b,"r"),"Bot: "+damaCount(s.b,"b"),"Hamle: "+s.moves])+'<div class="mg-checkers" style="display:grid;grid-template-columns:repeat(8,minmax(0,1fr));width:min(100%,420px);aspect-ratio:1;margin:12px auto;border:3px solid #6d83a4;border-radius:10px;overflow:hidden">';for(var r=0;r<8;r++)for(var c=0;c<8;c++){var ix=r*8+c,p=s.b[ix],dark=(r+c)%2===1,selected=s.sel===ix,possible=moves.indexOf(ix)>=0,back=dark?"#76563c":"#e8d9bf",piece=p?'<span style="display:grid;place-items:center;width:76%;height:76%;border-radius:50%;background:'+(damaSide(p)==="r"?"radial-gradient(circle at 35% 25%,#ff7777,#9e1425)":"radial-gradient(circle at 35% 25%,#657080,#101722)")+';border:3px solid '+(p===p.toUpperCase()?"#f4d36f":"#d5dce7")+';box-shadow:0 3px 5px #0009;color:#ffe99c;font-size:clamp(10px,3vw,18px);font-weight:950">'+(p===p.toUpperCase()?"♛":"")+'</span>':"";h+='<button data-mg="dama-cell" data-i="'+ix+'" style="display:grid;place-items:center;min-width:0;min-height:0;padding:0;border:0;background:'+(selected?"#e0b84a":possible?"#7cae78":back)+';outline:'+(possible?"2px solid #8ff0a5":"none")+'">'+piece+'</button>';}h+='</div><div class="mg-msg">'+s.msg+'</div><button class="mg-btn alt" data-mg="dama-reset">Yeni oyun</button>';return h;}
function damaHuman(i){if(s.done||s.turn!=="r")return;var piece=s.b[i];if(s.sel>=0){var move=s.legal.find(function(m){return m.from===s.sel&&m.to===i;});if(move){damaApply(s.b,move);s.moves++;var chain=move.cap>=0?damaMovesFor(s.b,move.to,"r",true):[];if(chain.length){s.forced=move.to;s.sel=move.to;s.legal=chain;s.msg="Zorunlu devam vuruşu: aynı taşla bir taş daha al.";damaStatus();return;}s.sel=-1;s.forced=-1;s.turn="b";damaStatus();if(!s.done){s.msg="Bot düşünüyor…";damaBot();}s.legal=damaLegal(s.b,"r",-1);return;}}if(damaSide(piece)==="r"){var legal=damaLegal(s.b,"r",s.forced);if(legal.some(function(m){return m.from===i;})){s.sel=i;s.legal=legal.filter(function(m){return m.from===i;});s.msg=s.forced>=0?"Aynı taşla devam et.":"Yeşil karelerden birine dokun.";}}}


