function bgInit(){var b=Array(24).fill(0);b[0]=2;b[11]=5;b[16]=3;b[18]=5;b[23]=-2;b[12]=-5;b[7]=-3;b[5]=-5;s={b:b,bar:[0,0],off:[0,0],dice:[],selected:-1,done:false,turn:0,msg:"Zar at ve taşlarını topla.",moves:0};bgRoll();}
function bgRoll(){var a=1+Math.floor(Math.random()*6),b=1+Math.floor(Math.random()*6);s.dice=a===b?[a,a,a,a]:[a,b];s.msg="Zarlar: "+a+" ve "+b+". Hamle seçeneklerinden birini seç.";s.selected=-1;}
function bgHome(side){if(s.bar[side]>0)return false;return side===0?s.b.slice(0,18).every(v=>v<=0):s.b.slice(6,24).every(v=>v>=0);}
function bgMoves(side,die){var out=[],bar=s.bar[side];if(bar>0){var to=side===0?24-die:die-1;if(to>=0&&to<24&&(side===0?s.b[to]>=-1:s.b[to]<=1))out.push({from:-1,to:to,die:die,hit:Math.abs(s.b[to])===1,enter:true});return out;}for(var from=0;from<24;from++){if(side===0?s.b[from]<=0:s.b[from]>=0)continue;var to=side===0?from+die:from-die,off=to<0||to>23;if(off){if(!bgHome(side))continue;var far=false;if(side===0){for(var q=from+1;q<24;q++)if(s.b[q]>0)far=true;if(to>23&&far)continue;}else{for(var q=0;q<from;q++)if(s.b[q]<0)far=true;if(to<0&&far)continue;}out.push({from:from,to:-2,die:die,hit:false,off:true});}else if(side===0?s.b[to]>=-1:s.b[to]<=1)out.push({from:from,to:to,die:die,hit:Math.abs(s.b[to])===1,enter:false});}return out;}
