function bgApply(side,m){if(m.enter){s.bar[side]--;if(m.hit){if(side===0){s.b[m.to]=0;s.bar[1]++;}else{s.b[m.to]=0;s.bar[0]++;}}if(side===0)s.b[m.to]++;else s.b[m.to]--;}else{if(side===0)s.b[m.from]--;else s.b[m.from]++;if(m.off){s.off[side]++;}else{if(m.hit){if(side===0){s.b[m.to]=0;s.bar[1]++;}else{s.b[m.to]=0;s.bar[0]++;}}if(side===0)s.b[m.to]++;else s.b[m.to]--;}}var ix=s.dice.indexOf(m.die);if(ix>=0)s.dice.splice(ix,1);s.moves++;if(s.off[side]>=15){s.done=true;s.winner=side;s.msg=side===0?"Tavlayı kazandın!":"Bot tavlayı kazandı.";} }
function bgScore(m,side){var score=m.off?100:m.hit?35:0;if(m.to>=0){score+=side===0?m.to*.35:(23-m.to)*.35;if(Math.abs(s.b[m.to])===1)score+=8;}if(m.from>=0){var left=side===0?23-m.from:m.from;score+=Math.max(0,6-left)*2;}return score+Math.random();}
function bgBot(){var guard=0;while(s.dice.length&&!s.done&&guard++<4){var options=bgAllMoves(1);if(!options.length){s.dice=[];break;}options.sort((a,b)=>bgScore(b,1)-bgScore(a,1));bgApply(1,options[0]);}if(s.done)return;s.turn=0;bgRoll();if(!bgAllMoves(0).length){s.turn=1;s.msg="Bu zarlarla hamlen yok. Bot oynuyor…";bgBot();return;}s.msg="Sıra sende. Zarına uygun hamleyi seç.";}
function bgMoveLabel(m){var a=m.from===-1?"Bar":String(m.from+1),b=m.off?"Topla":String(m.to+1);return a+" → "+b+"  (zar "+m.die+")";}
function bgHtml(){var h=stats(["Senin taşın: "+s.off[0]+"/15","Bot: "+s.off[1]+"/15","Bar: "+s.bar[0]+" · "+s.bar[1]])+'<div class="mg-card">Sen taşlarını 1’den 24’e, bot ters yönde ilerletir. İki rakip taşın bulunduğu nokta kapalıdır. Tek taş kırılır ve bara gider.</div><div class="mg-backgammon">';h+='<div class="mg-bg-row">';for(var i=23;i>=12;i--)h+=bgPoint(i);h+='</div><div class="mg-bg-middle">ZARLAR · '+(s.dice.join(" · ")||"—")+'</div><div class="mg-bg-row">';for(var j=0;j<12;j++)h+=bgPoint(j);h+='</div></div><div class="mg-msg">'+s.msg+'</div>';var moves=s.turn===0&&!s.done?bgAllMoves(0):[];if(moves.length){h+='<div class="mg-bg-moves">';moves.forEach(function(m){h+='<button class="mg-btn" data-mg="bg-move" data-from="'+m.from+'" data-to="'+m.to+'" data-die="'+m.die+'">'+bgMoveLabel(m)+'</button>';});h+='</div>';}if(s.done)h+='<div class="mg-big">'+(s.winner===0?"🏆":"🎲")+'</div>';h+='<button class="mg-btn alt" data-mg="bg-reset">Yeni oyun</button>';return h;}
function bgPoint(i){var v=s.b[i],count=Math.abs(v),owner=v>0?"you":v<0?"bot":"empty";return '<button class="mg-bg-point '+owner+'" data-mg="bg-point" data-i="'+i+'"><small>'+(i+1)+'</small><b>'+(count?count:"·")+'</b></button>';}
