function snakeInit(){var start=8*16+7;s={snake:[start,start-1,start-2],dir:"right",nextDir:"right",food:snakeFood([start,start-1,start-2]),score:0,best:Number(localStorage.getItem("arenaSnakeBest")||0),speed:180,running:false,done:false,msg:"Başla. Yön tuşlarıyla veya ekranı kaydırarak hareket et."};}
